#include "stdlib/blas/ext/base/dindex_of_greater_than_sorted.h"
#include "stdlib/strided/base/stride2offset.h"
#include "stdlib/blas/base/shared.h"

/**
* Returns the index of the first element in a sorted double-precision floating-point strided array which is greater than a specified search element.
*
* @param N             number of indexed elements
* @param searchElement search element
* @param X             sorted input array
* @param strideX       stride length
* @return              index
*/
CBLAS_INT API_SUFFIX(stdlib_strided_dindex_of_greater_than_sorted)( const CBLAS_INT N, const double searchElement, const double *X, const CBLAS_INT strideX ) {
	CBLAS_INT ox = stdlib_strided_stride2offset( N, strideX );
	return API_SUFFIX(stdlib_strided_dindex_of_greater_than_sorted_ndarray)( N, searchElement, X, strideX, ox );
}

/**
* Returns the index of the first element in a sorted double-precision floating-point strided array which is greater than a specified search element using alternative indexing semantics.
*
* @param N             number of indexed elements
* @param searchElement search element
* @param X             sorted input array
* @param strideX       stride length
* @param offsetX       starting index
* @return              index
*/
CBLAS_INT API_SUFFIX(stdlib_strided_dindex_of_greater_than_sorted_ndarray)( const CBLAS_INT N, const double searchElement, const double *X, const CBLAS_INT strideX, const CBLAS_INT offsetX ) {
	CBLAS_INT mid;
	CBLAS_INT lo;
	CBLAS_INT hi;

	if ( N <= 0 ) {
		return -1;
	}
	lo = 0;
	hi = N;
	while ( lo < hi ) {
		mid = lo + ( ( hi - lo ) / 2 );
		if ( searchElement < X[ offsetX + ( mid * strideX ) ] ) {
			hi = mid;
		} else {
			lo = mid + 1;
		}
	}
	if ( lo == N ) {
		return -1;
	}
	return lo;
}
